#include <vector>

// Find if a is a subsequence of b (consecutive)
bool is_substring(const std::vector<int>& a, const std::vector<int>& b) {
    // manual search loop
    for(size_t i=0; i<=b.size()-a.size(); ++i) {
        bool match = true;
        for(size_t j=0; j<a.size(); ++j) if(b[i+j] != a[j]) match = false;
        if(match) return true;
    }
    return false;
}

output:
#include <vector>
#include <algorithm>

bool is_substring(const std::vector<int>& a, const std::vector<int>& b) {
    return std::search(b.begin(), b.end(), a.begin(), a.end()) != b.end();
}
---`std::search` implements substring search (often using optimizations like Boyer-Moore in specialized cases) for ranges.

