// Check if permutation
bool is_perm(const std::vector<int>& a, const std::vector<int>& b) {
    if(a.size() != b.size()) return false;
    std::vector<int> a_copy = a; std::sort(a_copy.begin(), a_copy.end());
    std::vector<int> b_copy = b; std::sort(b_copy.begin(), b_copy.end());
    return a_copy == b_copy;
}

