// Lexicographical compare
bool lex_less(const std::vector<int>& a, const std::vector<int>& b) {
    size_t n = std::min(a.size(), b.size());
    for(size_t i=0; i<n; ++i) {
        if(a[i] < b[i]) return true;
        if(a[i] > b[i]) return false;
    }
    return a.size() < b.size();
}

